import PropTypes from 'prop-types';
import classnames from 'classnames';
import { useEffect, useRef, useState } from 'preact/hooks';
import MoreVertIcon from '@material-ui/icons/MoreVert';

import { shellsToBottles } from '../../../../user/slice';
import MessageStatus from './MessageStatus';
import MorePopover from './MorePopover';

import styles from './styles.module.scss';
import { Friend, Message } from '../../../slice/types';
import { FunctionalComponent } from 'preact';
import { UserDb } from '../../../../user/slice/types';

const OnlineStatus = ({ isOnline }) => {
  const ref = useRef(isOnline);
  const isChange = isOnline && !ref.current;
  return isOnline ? (
    <div className={`${styles.onlineStatus} ${isChange ? styles.animate : ''}`}>
      <div />
    </div>
  ) : null;
};

OnlineStatus.propTypes = {
  isOnline: PropTypes.bool.isRequired,
};

// -----------------------------------------------------------------------------

interface Props {
  friend: Friend | UserDb,
  handleRef: (ref: any) => unknown,
  loggedUser: UserDb,
  sortBy: string;
  isSelected: boolean;
  onClick: () => unknown,
  messages: Message[],
}

const FriendContainer: FunctionalComponent<Props> = ({
  friend,
  messages = [],
  onClick,
  handleRef,
  loggedUser,
  // isSelected,
  sortBy,
}: Props) => {
  const isOnline = friend.id === loggedUser.id || ('isOnline' in friend && friend.isOnline);
  const isYou = friend.id === loggedUser.id;
  const [isMoreOpen, setMoreOpen] = useState(false);

  const toggleMoreOpened = (evt) => {
    evt.stopPropagation();
    setMoreOpen(!isMoreOpen);
  };

  const counter = friend[sortBy];
  const ref = useRef({ counter, sortBy });
  const [gain, setGain] = useState(null);

  useEffect(() => {
    if (isYou) return null;
    const diff =
      shellsToBottles(counter) - shellsToBottles(ref.current.counter);
    if (ref.current.sortBy === sortBy && diff > 0) {
      setGain(diff);
      setTimeout(() => setGain(null), 2100);
    } else {
      setGain(null);
    }
  }, [counter, sortBy]);

  return (
    <li
      ref={handleRef}
      className={classnames([
        styles.friend,
        { [styles.isSelected]: !!gain, [styles.isActive]: !!gain },
      ])}
    >
      <div className={styles.element} onClick={onClick}>
        <OnlineStatus isOnline={isOnline} />

        {(messages || []).map((message, i) => (
          <MessageStatus key={message.id} message={message} index={i} />
        ))}

        <div>
          {friend.name} {isYou ? '(you)' : ''}
        </div>

        <div
          className={`${styles.friendCounter} ${gain ? styles.animate : ''}`}
        >
          <div>{shellsToBottles(counter)}</div>
          {gain && <span className={styles.gain}>+{gain}</span>}
        </div>

        {!isYou && (
          <button
            className={`${styles.moreButton} ${
              isMoreOpen ? styles.active : ''
            }`}
            onClick={toggleMoreOpened}
          >
            <MoreVertIcon />
          </button>
        )}
      </div>

      {isMoreOpen && <MorePopover friend={friend} onClose={toggleMoreOpened} />}
    </li>
  );
};

export default FriendContainer;
