import { useState } from 'preact/hooks';
import PropTypes from 'prop-types';

import { useDispatch, useSelector } from 'react-redux';

import StateIndicator from '../../../../../../shared/StateIndicator';
import { updateUser } from '../../../../../user/slice';
import { selectLoggedUser } from '../../../../../user/slice';
import Button from '../../../../../../shared/Button';

import styles from './styles.module.scss';
import { FunctionComponent } from 'preact';

// -----------------------------------------------------------------------------

const Form = ({ user, onBack, onSubmit }) => {
  const [name, setName] = useState(user.name);

  const handleSubmit = () => {
    onSubmit(name);
  };

  const handleChange = (evt) => {
    setName(evt.target.value);
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className={styles.textInput}>
        <label htmlFor="name">Name</label>
        <input
          required
          type="text"
          name="name"
          value={name}
          onChange={handleChange}
        />
      </div>

      <div className={styles.buttonsFooter}>
        <Button type="submit" variant="primary">
          Change
        </Button>
        <Button variant="link" onClick={onBack}>
          Cancel
        </Button>
      </div>
    </form>
  );
};

Form.propTypes = {
  user: PropTypes.object.isRequired,
  onSubmit: PropTypes.func.isRequired,
  onBack: PropTypes.func.isRequired,
};

type Types = 'form' | 'loading' | 'success' | 'error';


interface Props {
  changeView: () => unknown;
}

const ChangeName: FunctionComponent<Props> = ({ changeView }: Props) => {
  const dispatch = useDispatch();
  const [state, setState] = useState<{type: Types, message?: string}>({
    type: 'form',
    message: null,
  });

  const user = useSelector(selectLoggedUser);

  const goBack = () => changeView();

  const handleChange = async (name) => {
    setState({ type: 'loading' });
    try {
      // eslint-disable-next-line @typescript-eslint/await-thenable
      await dispatch(updateUser({ name }));
      setState({ type: 'success' });
    } catch (e) {
      const message = 'There was an error. Try again later or contact support.';
      setState({ type: 'error', message });
    }

    await new Promise((resolve) => setTimeout(resolve, 2000));

    setState({ type: 'form' });
  };

  if (state.type === 'form') {
    return <Form user={user} onBack={goBack} onSubmit={handleChange} />;
  }

  return <StateIndicator message={state.message} type={state.type} />;
};

export default ChangeName;
