import DoneIcon from '@material-ui/icons/Done';
import DoneAllIcon from '@material-ui/icons/DoneAll';

import styles from './styles.module.scss';
import { Message } from '../../../../slice/types';
import { FunctionComponent } from 'preact';

interface Props {
  message: Message;
  index: number;
}

const MessageStatus: FunctionComponent<Props> = ({ message, index }: Props) => (
  <div
    style={{ left: -30 * index - 35 }}
    className={`${styles.friendsMessageStatus} ${
      message.received ? styles.received : ''
    }`}
  >
    <span
      className={styles.thumbnail}
      style={{ backgroundImage: `url(${message.thumbnailSrc})` }}
    />

    <span className={styles.checkmark}>
      {message.received ? <DoneAllIcon /> : <DoneIcon />}
    </span>
  </div>
);

export default MessageStatus;
