import PropTypes from 'prop-types';
import { useState } from 'preact/hooks';

import CreateIcon from '@material-ui/icons/Create';
import BlockIcon from '@material-ui/icons/Block';
import ArrowBackIcon from '@material-ui/icons/ArrowBack';

import Popover from '../../../../../shared/Popover';

import ChangeName from './ChangeName';
import DisableGifs from './DisableGifs';

import styles from './styles.module.scss';
import { FunctionComponent } from 'preact/compat';

const VIEWS = {
  nav: 'NAV',
  username: 'USERNAME',
  disable: 'DISABLE',
};

const SettingsNav = ({ changeView }) => (
  <>
    <button
      className={styles.listButton}
      onClick={() => changeView(VIEWS.username)}
    >
      <CreateIcon className={styles.icon} />
      Change your name
    </button>

    <button
      className={styles.listButton}
      onClick={() => changeView(VIEWS.disable)}
    >
      <BlockIcon className={styles.icon} />
      Disable GIFs
    </button>
  </>
);

SettingsNav.propTypes = {
  changeView: PropTypes.func.isRequired,
};

const Title = ({ view, changeView }) => {
  const text = {
    [VIEWS.nav]: 'Settings',
    [VIEWS.username]: 'Change name',
    [VIEWS.disable]: 'Disable GIFs',
  }[view];

  return (
    <h2
      className={`${styles.title} ${
        view !== VIEWS.nav ? styles.nestedContent : ''
      }`}
    >
      {view !== VIEWS.nav && (
        <button onClick={() => changeView(VIEWS.nav)}>
          <ArrowBackIcon />
        </button>
      )}
      {text}
    </h2>
  );
};

Title.propTypes = {
  view: PropTypes.string.isRequired,
  changeView: PropTypes.func.isRequired,
};

const Settings: FunctionComponent = () => {
  const [isOpen, setOpen] = useState(false);
  const toggle = () => setOpen(!isOpen);

  const [view, setView] = useState(VIEWS.nav);
  const changeView = (newView?: string) => setView(newView || VIEWS.nav);

  const Content = {
    [VIEWS.nav]: SettingsNav,
    [VIEWS.username]: ChangeName,
    [VIEWS.disable]: DisableGifs,
  }[view];

  return (
    <div className={styles.friendsSettings}>
      <button className={styles.settingsBtn} onClick={toggle}>
        Settings
      </button>

      {isOpen && (
        <Popover onClose={toggle} className={styles.settingsPopover}>
          <Title view={view} changeView={changeView} />
          <Content changeView={changeView} />
        </Popover>
      )}
    </div>
  );
};

export default Settings;
